"""Inspect the workspace: list files and report sqlite databases (read-only)."""

import os
import sqlite3

print("Working directory:", os.getcwd())
print("\nFiles in workspace:")
for entry in sorted(os.listdir(".")):
    full = os.path.join(".", entry)
    if os.path.isfile(full):
        print(f"  {entry}  ({os.path.getsize(full)} bytes)")
    elif os.path.isdir(full):
        print(f"  {entry}/  (directory)")

print("\nSQLite databases found:")
found = False
for entry in sorted(os.listdir(".")):
    if entry.endswith(".db"):
        found = True
        print(f"\n--- {entry} ---")
        conn = sqlite3.connect(entry)
        try:
            tables = conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
            ).fetchall()
            if not tables:
                print("  (no tables)")
            for (name,) in tables:
                print(f"  table: {name}")
                for row in conn.execute(f'PRAGMA table_info("{name}")'):
                    print(f"    column: {row[1]}  type: {row[2]}  notnull: {row[3]}  default: {row[4]}  pk: {row[5]}")
        finally:
            conn.close()
if not found:
    print("  (none found)")

"""Inspect the local workspace for SQLite databases and report their schema.

Task-scoped helper: only reads file names and opens databases read-only.
No network, no writes, no destructive operations.
"""
import os
import sqlite3


def main() -> None:
    root = os.getcwd()
    entries = sorted(os.listdir(root))
    print(f"Working directory: {root}")
    print(f"All entries: {entries}")

    db_files = sorted(
        name for name in entries
        if name.lower().endswith(".db") and os.path.isfile(name)
    )
    if not db_files:
        print("No .db files found.")
        return

    for name in db_files:
        print(f"\n=== {name} ===")
        uri = f"file:{os.path.abspath(name)}?mode=ro"
        try:
            with sqlite3.connect(uri, uri=True) as conn:
                conn.row_factory = sqlite3.Row
                tables = conn.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                if not tables:
                    print("(no tables)")
                for table in tables:
                    tname = table["name"]
                    print(f"\n-- table: {tname}")
                    for row in conn.execute(f'PRAGMA table_info("{tname}")'):
                        print(dict(row))
        except sqlite3.Error as exc:
            print(f"Could not inspect {name}: {exc}")


if __name__ == "__main__":
    main()

